/* init.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "./context.js";

export function install(P) {


  /* ---------- init ---------- */

  function applySettingsFrom(saved) {
    P.state.volume = typeof saved.volume === "number" ? Math.min(1, Math.max(0, saved.volume)) : 1;
    P.state.muted = saved.muted === true;
    P.state.shuffle = saved.shuffle === true;
    P.state.repeat = ["off", "all", "one"].includes(saved.repeat) ? saved.repeat : "off";
    // Explicit choice always wins. Older saves have no flag: a non-HTML5
    // engine was a real choice, while the old built-in default moves to the
    // new JS-capable default (WaveSurfer).
    const savedEngine = P.ENGINES.includes(saved.engine) ? saved.engine : null;
    const explicit = !!savedEngine && (saved.engineExplicit === true || savedEngine !== "html5");
    P.state.engine = explicit ? savedEngine : P.detectDefaultEngine();
    P.state.engineExplicit = explicit;
    P.shufflePick = null;
    P.state.format = P.FORMATS.includes(saved.format) ? saved.format : "opus";
    P.state.autoNext = saved.autoNext !== false;
    P.state.rememberPosition = saved.rememberPosition !== false;
    P.state.crossfade = saved.crossfade !== false;
    const clampFade = (value, fallback) => {
      const n = Number(value);
      return Number.isFinite(n) ? Math.min(P.CROSSFADE_MAX_MS, Math.max(P.CROSSFADE_MIN_MS, Math.round(n))) : fallback;
    };
    // Migrate legacy single crossfadeMs setting.
    const legacy = clampFade(saved.crossfadeMs, P.DEFAULT_FADE_OUT_MS);
    P.state.fadeOutMs = saved.fadeOutMs == null ? legacy : clampFade(saved.fadeOutMs, P.DEFAULT_FADE_OUT_MS);
    P.state.fadeInMs = clampFade(saved.fadeInMs, P.DEFAULT_FADE_IN_MS);
    // New toggles default to on, including for older saves written before
    // these keys existed. The single persisted state is the only source of
    // truth for both the checkboxes and the audible envelopes.
    P.state.fadeOutEnabled = saved.fadeOutEnabled !== false;
    P.state.fadeInEnabled = saved.fadeInEnabled !== false;
    P.state.skipIntro = !!saved.skipIntro;
    const clampDb = (value, fallback) => {
      const n = Number(value);
      return Number.isFinite(n) ? Math.min(-12, Math.max(-60, Math.round(n))) : fallback;
    };
    const clampIntroMax = (value, fallback) => {
      const n = Number(value);
      return Number.isFinite(n) ? Math.min(P.INTRO_SCAN_MAX_SEC, Math.max(5, Math.round(n))) : fallback;
    };
    P.state.silenceDb = clampDb(saved.silenceDb, P.DEFAULT_SILENCE_DB);
    P.state.introMaxSec = clampIntroMax(saved.introMaxSec, P.DEFAULT_INTRO_MAX_SEC);
    P.state.playbackRate = P.clampPlaybackRate(saved.playbackRate);
    P.state.pitchMode = P.normalizePitchMode(saved.pitchMode || (saved.preservePitch === false ? "vinyl" : "preserve"));
    const modeIds = new Set(P.PLAYBACK_RATE_MODES.map((m) => m.id).concat(["custom"]));
    P.state.playbackMode = modeIds.has(saved.playbackMode) ? saved.playbackMode : "custom";
    const matchMode = P.PLAYBACK_RATE_MODES.find((m) => m.rate === P.state.playbackRate);
    if (matchMode && P.state.playbackMode === "custom") P.state.playbackMode = matchMode.id;
    P.state.preservePitch = P.state.pitchMode !== "vinyl";

    P.state.eqEnabled = saved.eqEnabled === true;
    P.state.limiterEnabled = saved.limiterEnabled !== false;
    P.state.limiterMode = P.LIMITER_MODES.includes(saved.limiterMode) ? saved.limiterMode : "dbfs";
    P.state.fxBakeDelayMs = P.normalizeBakeDelay(saved.fxBakeDelayMs);
    P.state.remixFormat = P.REMIX_FORMATS.includes(saved.remixFormat) ? saved.remixFormat : "wav";
    P.limiterEnabled = P.state.limiterEnabled;
    P.FX_KINDS.forEach((kind) => { P.state[`${kind}Enabled`] = saved[`${kind}Enabled`] === true; });
    Object.keys(P.FX_RANGES).forEach((key) => {
      const range = P.FX_RANGES[key];
      const value = Number(saved[key]);
      P.state[key] = Number.isFinite(value) ? P.clamp(value, range.min, range.max) : range.fallback;
    });
    const savedFilters = Array.isArray(saved.eqFilters) ? saved.eqFilters : null;
    if (savedFilters && savedFilters.length) {
      P.state.eqFilters = savedFilters.slice(0, 8).map((f, i) => P.normalizeEqFilter(f, i));
    } else {
      const savedGains = saved.eqGains && typeof saved.eqGains === "object" ? saved.eqGains : {};
      const migrated = [60,170,310,600,1000,3000,6000,12000,14000,16000]
        .map((freq, i) => ({ id: `m${freq}`, type: "peaking", freq, gain: Number(savedGains[String(freq)]) || 0, q: 1.1, enabled: true }))
        .filter((f) => f.gain !== 0);
      P.state.eqFilters = migrated.length ? migrated : P.DEFAULT_EQ_FILTERS.map((f) => ({ ...f }));
    }
    P.state.queue = Array.isArray(saved.queue)
      ? saved.queue.filter((item) => item && item.path && Array.isArray(item.tracks)).slice(0, 100)
      : [];

    P.audio.volume = P.state.volume;
    P.audio.muted = P.state.muted;
    P.volume.value = String(P.state.volume);

    P.applyShuffle();
    P.applyRepeat();
    P.updateMuteState();
    P.renderQueue();
    P.mountSettings();
    P.applyPlaybackRate();
    P.ensureMasterOutput();
    // A shared link can change the limiter mode after the context already
    // exists; drop the old graph so the restored mode is the audible one.
    if (P.audioContext) P.rebuildLimiter();
    P.ensureMainGain();
    if (P.state.eqEnabled) P.ensureEqChain();
    P.applyEqState();
    // The UI and the baked audio are both built from this restored state.
    P.applyFxState();
  }

  function restore() {
    const shared = P.readSharedSettings();
    const timeParam = P.readTimeParam();
    const saved = shared ? { ...P.loadSaved(), ...shared } : P.loadSaved();
    P.state.context = saved.context || null;
    P.state.current = saved.current || null;
    P.state.time = typeof saved.time === "number" ? saved.time : 0;
    // A link's timecode wins over the locally remembered position. The music
    // page will later select the shared album/track and apply it there too.
    if (timeParam !== null) P.state.time = timeParam;
    P.restoring = true;
    try { P.applySettingsFrom(saved); } finally { P.restoring = false; }
    if (shared) {
      P.saveState();
      P.clearShareParam();
      P.notify("settings");
    }
    if (!P.state.current || !P.state.current.path) return;
    P.showBar();
    P.renderMetadata();
    P.loadCurrent({ autoplay: false, startTime: timeParam !== null ? timeParam : (P.state.rememberPosition ? P.state.time : 0) });
  }

  // Shared links can also be opened through the site's SPA navigation, where
  // player.js is not re-executed. Apply the same settings without reloading
  // the page (and without touching the track that is currently playing).
  function applySharedSettings() {
    const shared = P.readSharedSettings();
    if (!shared) return false;
    // Engine/format changes must also re-init the active track, exactly as
    // they do when the visitor changes the selects in the settings form.
    if (shared.engine && shared.engine !== P.state.engine) P.setEngine(shared.engine);
    if (shared.format && shared.format !== P.state.format) P.setFormat(shared.format);
    const current = {
      ...P.loadSaved(),
      ...Object.fromEntries(P.SHARE_KEYS.map((key) => [key, P.state[key]])),
      context: P.state.context,
      current: P.state.current,
      time: P.state.time,
      queue: P.getQueue(),
      volume: P.state.volume,
      muted: P.state.muted,
      shuffle: P.state.shuffle,
      repeat: P.state.repeat,
      ...shared,
    };
    P.applySettingsFrom(current);
    P.saveState();
    P.clearShareParam();
    P.notify("settings");
    return true;
  }
  Object.assign(P, { applySettingsFrom, restore, applySharedSettings });
}
